                next_node, dist = dp[k-1][u]
                next_next_node, next_dist = dp[k-1][next_node]
                dp[k][u] = (next_next_node, dist + next_dist)

    # BFS with binary lifting to find shortest path
    dist = [float('inf')] * n
    dist[s] = 0
    visited = [False] * n
    q = deque([s])
    visited[s] = True

