def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    from collections import defaultdict
    adj = defaultdict(list)
    for u, v, w in edges:
        adj[u].append((v, w))

    # Heuristic function: Manhattan distance (can be replaced with other heuristics)
    def heuristic(u, t):
        return abs(u - t)

    # Priority queue for A* algorithm
    pq = []
    heapq.heappush(pq, (0, s, s))  # (priority, current node, previous node)

    # Track visited nodes with their shortest distance
    dist = {s: 0}
    prev = {s: None}

    while pq:
        current_dist, u, _ = heapq.heappop(pq)

        # If we reached the target
        if u == t:
            return current_dist

        # Skip if a shorter path to u has already been found
        if current_dist > dist.get(u, float('inf')):
            continue

        for v, w in adj[u]:
            new_dist = current_dist + w
            if new_dist < dist.get(v, float('inf')):
                dist[v] = new_dist
                prev[v] = u
                heapq.heappush(pq, (new_dist + heuristic(v, t), v, u))

