                return True
            for v in new_adj[u]:
                if not visited[v]:
                    visited[v] = True
                    queue.append(v)
        return False

    # Binary search on possible weights
    low = 0
    high = 10000  # since max weight is 100 and max edges is 100, max possible path weight is 100 * 100 = 10000
    answer = -1

    while low <= high:
        mid = (low + high) // 2
        if has_path_with_weight_at_most(mid):
            answer = mid
            high = mid - 1
        else:
