from collections import defaultdict

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    adj = defaultdict(list)
    for u, v, w in edges:
        adj[u].append((v, w))

    # Function to calculate path weight
    def path_weight(path):
        return sum(w for _, w in path)

    # Initialize population with random paths
    def generate_path():
        path = [s]
        current = s
        while True:
            if current == t:
                break
            if current not in adj:
                return None
            next_nodes = adj[current]
            next_node, _ = random.choice(next_nodes)
            if next_node not in path:
                path.append(next_node)
                current = next_node
            else:
                break
        return path if current == t else None

    # Evaluate fitness of a path
    def evaluate(path):
        if not path or path[0] != s or path[-1] != t:
            return float('inf')
        return path_weight(path)

    # Crossover function
    def crossover(path1, path2):
        if not path1 or not path2:
            return None
        if path1[0] != s or path1[-1] != t or path2[0] != s or path2[-1] != t:
            return None
        split = random.randint(1, min(len(path1), len(path2)) - 1)
        child1 = path1[:split] + path2[split:]
        child2 = path2[:split] + path1[split:]
        return child1 if path_weight(child1) < path_weight(child2) else child2

    # Mutation function
    def mutate(path):
        if not path or path[0] != s or path[-1] != t:
            return None
        new_path = list(path)
        i = random.randint(1, len(new_path) - 2)
        if new_path[i] in adj:
            next_nodes = adj[new_path[i]]
            if next_nodes:
                next_node, _ = random.choice(next_nodes)
                new_path[i] = next_node
        return new_path

    # Genetic algorithm
    population_size = 100
    population = [generate_path() for _ in range(population_size)]
    population = [p for p in population if p]

    for _ in range(1000):
        if not population:
            break
        population.sort(key=lambda x: evaluate(x))
        elites = population[:5]
        new_population = elites
        while len(new_population) < population_size:
            p1, p2 = random.sample(population, 2)
            child = crossover(p1, p2)
            if child:
                new_population.append(child)
        population = new_population

    best_path = min(population, key=evaluate)
    if not best_path:
        return -1
    return path_weight(best_path)

